patch='--- a/drivers/gpu/drm/amd/amdgpu/amdgpu_ib.c\n+++ b/drivers/gpu/drm/amd/amdgpu/amdgpu_ib.c\n@@ -27,6 +27,7 @@\n  *          Christian König\n  */\n #include <linux/seq_file.h>\n+#include <linux/moduleparam.h>\n #include <linux/slab.h>\n \n #include <drm/amdgpu_drm.h>\n@@ -34,6 +35,55 @@\n #include "amdgpu.h"\n #include "atom.h"\n #include "amdgpu_trace.h"\n+\n+/* Diagnostic only: arm after boot; captures CPU-owned command-ring storage.\n+ * No MMIO, GPU submissions, fence processing or recovery from this helper.\n+ */\n+static bool polaris11_submit_trace;\n+module_param_named(polaris11_submit_trace, polaris11_submit_trace, bool, 0600);\n+MODULE_PARM_DESC(polaris11_submit_trace, "Trace first 16 Polaris11 GFX envelopes before publication");\n+static atomic_t polaris11_submit_trace_count = ATOMIC_INIT(0);\n+\n+static void amdgpu_ib_trace_envelope(struct amdgpu_ring *ring, u64 start,\n+                                   unsigned int num_ibs, struct amdgpu_ib *ibs,\n+                                   struct amdgpu_job *job)\n+{\n+ unsigned int id, i, count;\n+ u64 end;\n+ if (!READ_ONCE(polaris11_submit_trace) ||\n+     ring->adev->asic_type != CHIP_POLARIS11 ||\n+     ring->funcs->type != AMDGPU_RING_TYPE_GFX)\n+  return;\n+ id = atomic_inc_return(&polaris11_submit_trace_count);\n+ if (id > 16)\n+  return;\n+ end = ring->wptr;\n+ count = min_t(u64, (end - start) & ring->ptr_mask, 512);\n+ dev_info(ring->adev->dev,\n+          "SUBMIT_ENV id=%u ring=%s start=%llu end=%llu count=%u truncated=%u sw_le=%u vmid=%u sync=%u last=%u\\n",\n+          id, ring->name, (unsigned long long)start, (unsigned long long)end,\n+          count, ((end - start) & ring->ptr_mask) > count,\n+          amdgpu_ring_uses_sw_le(ring), job ? AMDGPU_JOB_GET_VMID(job) : 0,\n+          READ_ONCE(ring->fence_drv.sync_seq),\n+          atomic_read(&ring->fence_drv.last_seq));\n+ if (ring->fence_drv.cpu_addr) {\n+  u32 raw = READ_ONCE(*ring->fence_drv.cpu_addr);\n+  dev_info(ring->adev->dev,\n+           "SUBMIT_ENV_FENCE id=%u addr=%016llx bytes=%4ph decoded=%u\\n",\n+           id, (unsigned long long)ring->fence_drv.gpu_addr, &raw,\n+           le32_to_cpu((__force __le32)raw));\n+ }\n+ for (i = 0; i < num_ibs && i < 16; i++)\n+  dev_info(ring->adev->dev,\n+           "SUBMIT_ENV_IB id=%u n=%u addr=%016llx dw=%u flags=%x le=%u\\n",\n+           id, i, (unsigned long long)ibs[i].gpu_addr, ibs[i].length_dw,\n+           ibs[i].flags, ibs[i].is_le);\n+ for (i = 0; i < count; i++) {\n+  u32 raw = READ_ONCE(ring->ring[(start + i) & ring->buf_mask]);\n+  dev_info(ring->adev->dev, "SUBMIT_ENV_DW id=%u n=%u bytes=%4ph\\n",\n+           id, i, &raw);\n+ }\n+}\n \n #define AMDGPU_IB_TEST_TIMEOUT\tmsecs_to_jiffies(1000)\n #define AMDGPU_IB_TEST_GFX_XGMI_TIMEOUT\tmsecs_to_jiffies(2000)\n@@ -142,6 +192,7 @@\n \tint vmid = AMDGPU_JOB_GET_VMID(job);\n \tbool need_pipe_sync = false;\n \tunsigned int cond_exec;\n+\tu64 tabor_submit_start;\n \n \tunsigned int i;\n \tint r = 0;\n@@ -192,6 +243,8 @@\n \t\treturn r;\n \t}\n \n+\ttabor_submit_start = ring->wptr;\n+\n \tneed_ctx_switch = ring->current_ctx != fence_ctx;\n \tif (ring->funcs->emit_pipeline_sync && job &&\n \t    ((tmp = amdgpu_sync_get_fence(&job->explicit_sync)) ||\n@@ -310,6 +363,7 @@\n \t\tring->funcs->emit_wave_limit(ring, false);\n \n \tamdgpu_ring_ib_end(ring);\n+\tamdgpu_ib_trace_envelope(ring, tabor_submit_start, num_ibs, ibs, job);\n \tamdgpu_ring_commit(ring);\n \treturn 0;\n }\n'
